import {db,auth,readableError} from './firebase-client.js?v=20261001-story-pages';
import {onAuthStateChanged,signInWithEmailAndPassword,signOut,setPersistence,browserSessionPersistence} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js';
import {collection,doc,getDocFromServer,onSnapshot,runTransaction,serverTimestamp,writeBatch} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js';
import {validateSong,fingerprint,safeLink,vinylTheme} from './song-model.js?v=20261001-story-pages';
import {startSettings,stopSettings,settingsUnsaved} from './admin-settings.js?v=20261001-story-pages';
import {startProfile,stopProfile,profileUnsaved} from './admin-profile.js?v=20261001-story-pages';
import {downloadCSV} from './admin-utils.js?v=20261001-story-pages';
const $=s=>document.querySelector(s),form=$('#song-form'),fields=['title','artist','year','category','date','meta','detail','description','lyric','youtube','spotify','appleMusic','itunes','soundcloud'];
const platforms={youtube:'YouTube',spotify:'Spotify',appleMusic:'Apple Music',itunes:'iTunes',soundcloud:'SoundCloud'},categoryLabels={solo:'Solo','emcee-l':'Solo',emcee_l:'Solo','bai-rieng':'Solo',dsp:'Khác'};
const esc=v=>String(v??'').normalize('NFC').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
let user=null,allowed=false,unsubs=[],generation=0,records=[],editing=null,dirty=false,busy=false,page=1,selected=new Set(),loaded={songs:false,songDrafts:false};
function message(text,kind='',target='#status'){$(target).textContent=text;$(target).className='admin-status '+kind;}
function preview(){form.elements.vinylColor.value=vinylTheme(Object.fromEntries(new FormData(form)));$('#preview-title').textContent=form.elements.title.value||'Tên ca khúc';$('#preview-artist').textContent=form.elements.artist.value||'Nghệ sĩ';$('#preview-cover').dataset.vinyl=form.elements.vinylColor.value;}
function clearEditor(){$('#add-song-panel').close();form.reset();editing=null;dirty=false;$('#form-heading').textContent='Thêm ca khúc';$('#record-id').textContent='Bản ghi mới';$('#delete-song').hidden=true;$('#save-draft').textContent='Lưu nháp';message('','','#form-status');preview();}
function setBusy(v){busy=v;$('#editor-fields').disabled=v;$('#new-song').disabled=v;$('#logout').disabled=v;document.querySelectorAll('[data-edit],[data-copy],[data-delete]').forEach(b=>b.disabled=v);}
function key(r){return r._collection+'/'+r.id;}
function links(r){return Object.entries(platforms).filter(([k])=>safeLink(r[k],k));}
function filtered(){const q=norm($('#admin-search').value),year=$('#filter-year').value,cat=$('#filter-category').value,status=$('#filter-status').value;return records.filter(r=>norm([r.title,r.artist,r.lyric].join(' ')).includes(q)&&(year==='all'||year==='unknown'&&r.year==null||String(r.year)===year)&&(cat==='all'||r.category===cat)&&(status==='all'||status==='featured'&&r.featured===true&&r._collection==='songs'||r._collection===status)).sort((a,b)=>(b.year||0)-(a.year||0)||String(a.title).localeCompare(String(b.title),'vi'));}
function hasLyric(song){return typeof song.lyric==='string' && song.lyric.trim().length>0;}
function lyricBadge(song){const present=hasLyric(song);return `<span class="lyric-badge ${present?'has-lyric':'missing-lyric'}">${present?'✓ Có lời bài hát':'Chưa có lời'}</span>`;}
function renderList(){const result=filtered();page=Math.min(page,Math.max(1,Math.ceil(result.length/15)));const visible=result.slice((page-1)*15,page*15);$('#song-list').innerHTML=visible.length?visible.map(r=>`<tr><td><input type="checkbox" data-select="${esc(key(r))}" aria-label="Chọn ${esc(r.title)}" ${selected.has(key(r))?'checked':''}></td><td><div class="song-table-name"><div class="mini-disc" data-vinyl="${vinylTheme(r)}"><span class="vinyl-spin orgel-disc rotating-carousel" aria-hidden="true"><span class="orgel-ring orgel-ring-outer"><span class="orgel-ring orgel-ring-inner"><span class="orgel-hub"><span class="orgel-spindle"><span></span></span></span></span></span></span></div><div><h3>${esc(r.title)}</h3><small>${esc(r.artist)}</small>${lyricBadge(r)}</div></div></td><td>${r.year??'Chưa rõ năm'}<br><small>${esc(categoryLabels[r.category]||r.category)}</small></td><td><div class="platform-tags">${links(r).map(([k,n])=>`<a href="${esc(safeLink(r[k],k))}" target="_blank" rel="noopener noreferrer">${n} ↗</a>`).join('')||'<small>Chưa có liên kết</small>'}</div></td><td><span class="admin-badge">${r._collection==='songDrafts'?'Bản nháp':r.featured?'★ Đã ghim':'Hiển thị'}</span></td><td><div class="row-actions"><button class="secondary" data-edit="${esc(key(r))}" ${busy?'disabled':''}>Sửa</button><button class="secondary" data-copy="${esc(key(r))}" ${busy?'disabled':''}>Nhân bản</button><button class="danger" data-delete="${esc(key(r))}" ${busy?'disabled':''}>Xóa</button></div></td></tr>`).join(''):`<tr><td colspan="6">${loaded.songs?'Không có bài phù hợp.':'Đang tải dữ liệu…'}</td></tr>`;$('#list-status').textContent=`${result.length?((page-1)*15+1):0}–${Math.min(page*15,result.length)} / ${result.length} bài · ${selected.size} đã chọn`;$('#page-number').textContent=`${page} / ${Math.max(1,Math.ceil(result.length/15))}`;$('#prev-page').disabled=page<=1;$('#next-page').disabled=page*15>=result.length;$('#select-page').checked=visible.length>0&&visible.every(r=>selected.has(key(r)));$('#select-page').indeterminate=visible.some(r=>selected.has(key(r)))&&!$('#select-page').checked;$('#export-selected').disabled=!selected.size;}
function updateOverview(){const pub=records.filter(r=>r._collection==='songs');$('#metric-songs').textContent=loaded.songs?pub.length:'—';$('#metric-drafts').textContent=loaded.songDrafts?records.filter(r=>r._collection==='songDrafts').length:'—';$('#metric-featured').textContent=loaded.songs?pub.filter(r=>r.featured).length:'—';$('#metric-links').textContent=loaded.songs?pub.filter(r=>links(r).length).length:'—';$('#coverage-bars').innerHTML=Object.entries(platforms).map(([k,n])=>{const count=pub.filter(r=>safeLink(r[k],k)).length;return `<div class="coverage-row"><span>${n}</span><progress value="${count}" max="${Math.max(pub.length,1)}" aria-label="${n}"></progress><span>${count} bài · ${pub.length?Math.round(count/pub.length*100):0}%</span></div>`;}).join('');for(const [id,values,first] of [['filter-year',[...new Set(records.map(r=>r.year))].sort((a,b)=>(b||0)-(a||0)),'Tất cả năm'],['filter-category',[...new Set(records.map(r=>r.category).filter(Boolean))].sort(),'Mọi nhóm']]){const old=$('#'+id).value;$('#'+id).innerHTML=`<option value="all">${first}</option>`+values.map(v=>`<option value="${esc(v??'unknown')}">${esc(v??'Chưa rõ năm')}</option>`).join('');$('#'+id).value=[...$('#'+id).options].some(o=>o.value===old)?old:'all';}selected=new Set([...selected].filter(k=>records.some(r=>key(r)===k)));renderList();}
function reset(){if(busy||dirty&&!confirm('Bỏ các thay đổi chưa lưu?'))return;clearEditor();$('#add-song-panel').showModal();$('#title').focus();}
function openRecord(r,copy=false){if(busy||dirty&&!confirm('Bỏ các thay đổi chưa lưu?'))return;clearEditor();if(!copy)editing=r;for(const k of fields)form.elements[k].value=r[k]??'';form.elements.vinylColor.value=['pink','rose','burgundy'].includes(r.vinylColor)?r.vinylColor:'pink';form.elements.featured.checked=r.featured===true;if(copy){form.elements.title.value=r.title+' (bản sao)';dirty=true;}$('#form-heading').textContent=copy?'Nhân bản ca khúc':'Chỉnh sửa ca khúc';$('#record-id').textContent=copy?'Bản sao chưa lưu':r.id;$('#delete-song').hidden=copy;$('#save-draft').textContent=r._collection==='songs'&&!copy?'Chuyển về nháp':'Lưu nháp';preview();$('#add-song-panel').showModal();$('#title').focus();}
function conflict(old,r){return !old.exists()||fingerprint(old.data())!==r._fingerprint;}
async function save(target){if(busy||!allowed||!user)return;if(!form.reportValidity())return;let data;try{data=validateSong(Object.fromEntries(new FormData(form)));data.vinylColor=form.elements.vinylColor.value;data.featured=form.elements.featured.checked;}catch(e){message(e.message,'error','#form-status');return;}const current=editing;if(current?._collection==='songs'&&target==='songDrafts'&&!confirm('Chuyển bài này về nháp sẽ gỡ bài khỏi website. Tiếp tục?'))return;setBusy(true);message('Đang lưu…','','#form-status');try{const dest=current?doc(db,target,current.id):doc(collection(db,target));await runTransaction(db,async tx=>{let old;if(current){old=await tx.get(doc(db,current._collection,current.id));if(conflict(old,current))throw new Error('CONFLICT');}if(!current||target!==current._collection){const exists=await tx.get(dest);if(exists.exists())throw new Error('DEST_EXISTS');}const stamps={updatedAt:serverTimestamp(),updatedBy:user.uid};if(current&&target===current._collection)tx.update(dest,{...data,...stamps});else{const previous=old?.data()||{};tx.set(dest,{...previous,...data,...stamps,createdAt:previous.createdAt||serverTimestamp()});if(current)tx.delete(doc(db,current._collection,current.id));}});clearEditor();message(target==='songs'?'Đã lưu và hiển thị trên website.':'Đã lưu bản nháp riêng tư.','success');}catch(e){message(e.message==='CONFLICT'?'Bản ghi đã thay đổi. Giữ lại nội dung đang nhập và mở lại bài trước khi lưu.':e.message==='DEST_EXISTS'?'Đã có bản ghi trùng ID ở nơi nhận. Không chuyển để tránh ghi đè.':readableError(e),'error','#form-status');}finally{setBusy(false);}}
async function deleteRecord(r){if(busy||!allowed||!confirm(`Xóa vĩnh viễn “${r.title}”?`))return;setBusy(true);try{await runTransaction(db,async tx=>{const ref=doc(db,r._collection,r.id),old=await tx.get(ref);if(conflict(old,r))throw new Error('CONFLICT');tx.delete(ref);});if(editing&&key(editing)===key(r))clearEditor();message('Đã xóa ca khúc.','success');}catch(e){message(e.message==='CONFLICT'?'Ca khúc vừa thay đổi. Mở lại bài trước khi xóa.':readableError(e),'error');}finally{setBusy(false);}}

async function bulkDelete(){
 if(busy||!allowed||!selected.size)return;
 const rows=records.filter(r=>selected.has(key(r)));
 if(!confirm(`Xóa vĩnh viễn ${rows.length} bài hát đã chọn?`))return;
 setBusy(true);
 try{
   const batch=writeBatch(db);
   rows.forEach(r=>batch.delete(doc(db,r._collection,r.id)));
   await batch.commit();
   selected.clear();
   message(`Đã xóa ${rows.length} bài hát.`,'success');
 }catch(e){message(readableError(e),'error');}
 finally{setBusy(false);}
}
function exportRows(rows){downloadCSV('longs-vault-songs.csv',['id','status',...fields,'vinylColor','featured'],rows.map(r=>[r.id,r._collection,...fields.map(k=>r[k]??''),r.vinylColor||'pink',!!r.featured]));}
onAuthStateChanged(auth,async account=>{const ticket=++generation;unsubs.forEach(f=>f());unsubs=[];stopSettings();stopProfile();user=account;allowed=false;records=[];selected.clear();loaded={songs:false,songDrafts:false};$('#admin-panel').hidden=true;$('#top-actions').hidden=true;$('#access-panel').hidden=true;$('#login-panel').hidden=!!account;$('#logout').hidden=!account;if(!account){clearEditor();message('Đăng nhập để quản lý kho nhạc.');return;}message('Đang kiểm tra quyền admin…');try{const role=await getDocFromServer(doc(db,'admins',account.uid));if(ticket!==generation)return;if(!role.exists()||role.data().active!==true){$('#access-panel').hidden=false;$('#account-uid').textContent=account.uid;message('Tài khoản chưa được cấp quyền admin.','error');return;}allowed=true;$('#admin-panel').hidden=false;$('#top-actions').hidden=false;$('#account-email').textContent=account.email;clearEditor();message('Đã kết nối tài khoản quản trị.','success');$('#list-error').hidden=true;startSettings(account);startProfile(account);for(const name of ['songs','songDrafts'])unsubs.push(onSnapshot(collection(db,name),{includeMetadataChanges:true},snap=>{if(ticket!==generation||snap.metadata.fromCache)return;loaded[name]=true;records=records.filter(r=>r._collection!==name).concat(snap.docs.map(d=>({...d.data(),id:d.id,_collection:name,_fingerprint:fingerprint(d.data())})));updateOverview();},e=>{if(ticket!==generation)return;$('#list-error').hidden=false;$('#list-error').textContent=(name==='songDrafts'?'Chưa đọc được bản nháp. Cập nhật Rules mới cho songDrafts. ':'')+readableError(e);}));}catch(e){if(ticket!==generation)return;$('#access-panel').hidden=false;$('#account-uid').textContent=account.uid;message(readableError(e),'error');}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-button').disabled=true;try{await setPersistence(auth,browserSessionPersistence);await signInWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);$('#password').value='';}catch(e){message(readableError(e),'error');}finally{$('#login-button').disabled=false;}});
$('#logout').addEventListener('click',async()=>{if(busy||(dirty||settingsUnsaved()||profileUnsaved())&&!confirm('Đăng xuất và bỏ thay đổi chưa lưu?'))return;try{await signOut(auth);}catch(e){message(readableError(e),'error');}});

form.addEventListener('input',()=>{dirty=true;preview();});form.addEventListener('submit',e=>{e.preventDefault();save('songs');});$('#save-draft').addEventListener('click',()=>save('songDrafts'));$('#new-song').addEventListener('click',reset);
function cancelEditor(){if(busy||dirty&&!confirm('Bỏ các thay đổi chưa lưu?'))return;clearEditor();}
$('#cancel-edit').addEventListener('click',cancelEditor);$('#add-song-panel').addEventListener('cancel',e=>{e.preventDefault();cancelEditor();});
$('#delete-song').addEventListener('click',()=>editing&&deleteRecord(editing));
for(const id of ['admin-search','filter-year','filter-category','filter-status'])$('#'+id).addEventListener(id==='admin-search'?'input':'change',()=>{page=1;renderList();});$('#prev-page').addEventListener('click',()=>{page--;renderList();});$('#next-page').addEventListener('click',()=>{page++;renderList();});
$('#song-list').addEventListener('click',e=>{for(const [attr,fn] of [['edit',r=>openRecord(r)],['copy',r=>openRecord(r,true)],['delete',deleteRecord]]){const b=e.target.closest('[data-'+attr+']');if(b){const r=records.find(r=>key(r)===b.dataset[attr]);if(r)fn(r);}}});$('#song-list').addEventListener('change',e=>{if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);renderList();}});$('#select-page').addEventListener('change',e=>{filtered().slice((page-1)*15,page*15).forEach(r=>e.target.checked?selected.add(key(r)):selected.delete(key(r)));renderList();});$('#export-all').addEventListener('click',()=>exportRows(filtered()));$('#export-selected').addEventListener('click',()=>exportRows(records.filter(r=>selected.has(key(r)))));
$('#delete-selected').addEventListener('click',bulkDelete);$('#export-coverage').addEventListener('click',()=>{const pub=records.filter(r=>r._collection==='songs');downloadCSV('longs-vault-platforms.csv',['platform','songs_with_link','total_songs'],Object.entries(platforms).map(([k,n])=>[n,pub.filter(r=>safeLink(r[k],k)).length,pub.length]));});
window.addEventListener('beforeunload',e=>{if(dirty||busy||settingsUnsaved()||profileUnsaved()){e.preventDefault();e.returnValue='';}});
